import java.util.*;
public class Main {
    static int[] parent, size;
    static int find(int x) { while(parent[x]!=x){parent[x]=parent[parent[x]];x=parent[x];}return x; }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n=sc.nextInt(), m=sc.nextInt();
        parent=new int[n+1]; size=new int[n+1];
        for(int i=0;i<=n;i++){parent[i]=i;size[i]=1;}
        int maxSz=1;
        while(m-->0){
            int u=sc.nextInt(),v=sc.nextInt();
            int ru=find(u),rv=find(v);
            if(ru!=rv){
                if(size[ru]<size[rv]){int t=ru;ru=rv;rv=t;}
                parent[rv]=ru;size[ru]+=size[rv];
                maxSz=Math.max(maxSz,size[ru]);
            }
            System.out.println(maxSz);
        }
    }
}
